package com.nthexperience.desktop.fixture;

import android.database.*;
import android.os.*;
import android.provider.*;
import java.io.*;
import java.util.*;

/** Separate test APK/UID. Its private files never exist in the launcher APK. */
public final class FixtureProvider extends DocumentsProvider {
    static final String AUTHORITY="com.nthexperience.desktop.fixture.documents";
    private static final String[] DOC={"document_id","_display_name","mime_type","_size","last_modified","flags"};
    @Override public boolean onCreate(){new File(getContext().getFilesDir(),"root").mkdirs();new File(getContext().getFilesDir(),"readonly").mkdirs();return true;}
    private File file(String id)throws FileNotFoundException{int at=id.indexOf(':');if(at<0)throw new FileNotFoundException();String root=id.substring(0,at);if(!root.equals("root")&&!root.equals("readonly"))throw new FileNotFoundException();try{File base=new File(getContext().getFilesDir(),root).getCanonicalFile(),value=new File(base,id.substring(at+1)).getCanonicalFile();if(!value.equals(base)&&!value.toPath().startsWith(base.toPath()))throw new FileNotFoundException();return value;}catch(IOException ex){throw new FileNotFoundException();}}
    private String id(File file)throws FileNotFoundException{try{for(String root:new String[]{"root","readonly"}){File base=new File(getContext().getFilesDir(),root).getCanonicalFile();if(file.getCanonicalFile().toPath().startsWith(base.toPath()))return root+":"+base.toPath().relativize(file.getCanonicalFile().toPath()).toString();}}catch(IOException ignored){}throw new FileNotFoundException();}
    private int flags(String id,File file){if(id.startsWith("readonly:")||file.getName().equals("ReadOnly.txt"))return 0;return DocumentsContract.Document.FLAG_SUPPORTS_DELETE|DocumentsContract.Document.FLAG_SUPPORTS_RENAME|(file.isDirectory()?DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE:DocumentsContract.Document.FLAG_SUPPORTS_WRITE);}
    private void row(MatrixCursor cursor,String id,File file){MatrixCursor.RowBuilder row=cursor.newRow();for(String column:cursor.getColumnNames())switch(column){case "document_id":row.add(id);break;case "_display_name":row.add(id.endsWith(":")?(id.startsWith("root")?"Nth Test Files":"Nth Read Only"):file.getName());break;case "mime_type":row.add(file.isDirectory()?DocumentsContract.Document.MIME_TYPE_DIR:file.getName().endsWith(".txt")?"text/plain":"application/octet-stream");break;case "_size":row.add(file.length());break;case "last_modified":row.add(file.lastModified());break;case "flags":row.add(flags(id,file));break;default:row.add(null);}}
    @Override public Cursor queryRoots(String[] projection){String[] columns=projection==null?new String[]{"root_id","document_id","title","flags","mime_types"}:projection;MatrixCursor cursor=new MatrixCursor(columns);MatrixCursor.RowBuilder row=cursor.newRow();for(String column:columns)switch(column){case "root_id":row.add("root");break;case "document_id":row.add("root:");break;case "title":row.add("Nth isolated test files");break;case "flags":row.add(DocumentsContract.Root.FLAG_SUPPORTS_CREATE|DocumentsContract.Root.FLAG_SUPPORTS_IS_CHILD);break;case "mime_types":row.add("*/*");break;default:row.add(null);}return cursor;}
    @Override public Cursor queryDocument(String documentId,String[] projection)throws FileNotFoundException{File file=file(documentId);if(!file.exists())throw new FileNotFoundException();MatrixCursor cursor=new MatrixCursor(projection==null?DOC:projection);row(cursor,documentId,file);return cursor;}
    @Override public Cursor queryChildDocuments(String parentId,String[] projection,String order)throws FileNotFoundException{File parent=file(parentId);if(!parent.isDirectory())throw new FileNotFoundException();MatrixCursor cursor=new MatrixCursor(projection==null?DOC:projection);File[] children=parent.listFiles();if(children!=null){Arrays.sort(children,Comparator.comparing(File::getName));for(File child:children)row(cursor,id(child),child);}return cursor;}
    @Override public ParcelFileDescriptor openDocument(String documentId,String mode,CancellationSignal signal)throws FileNotFoundException{File file=file(documentId);if(!file.exists())throw new FileNotFoundException();if(!mode.equals("r")&&flags(documentId,file)==0)throw new FileNotFoundException("Read only");
        if(mode.equals("r")&&(file.getName().equals("Slow.bin")||file.getName().equals("Broken.bin"))){try{ParcelFileDescriptor[] pipe=ParcelFileDescriptor.createPipe();new Thread(()->{try(OutputStream out=new ParcelFileDescriptor.AutoCloseOutputStream(pipe[1]);InputStream in=new FileInputStream(file)){byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1){out.write(bytes,0,n);if(file.getName().equals("Broken.bin"))break;Thread.sleep(8);}}catch(Exception ignored){}},"fixture-stream").start();return pipe[0];}catch(IOException ex){throw new FileNotFoundException();}}
        return ParcelFileDescriptor.open(file,ParcelFileDescriptor.parseMode(mode));}
    private void writable(String id,int flag)throws FileNotFoundException{if((flags(id,file(id))&flag)==0)throw new FileNotFoundException("Read only");}
    @Override public String createDocument(String parentId,String mime,String displayName)throws FileNotFoundException{writable(parentId,DocumentsContract.Document.FLAG_DIR_SUPPORTS_CREATE);String clean=clean(displayName);File target=new File(file(parentId),clean);if(target.exists())throw new FileNotFoundException("Already exists");try{if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime)){if(!target.mkdir())throw new IOException();}else if(!target.createNewFile())throw new IOException();return id(target);}catch(IOException ex){throw new FileNotFoundException();}}
    @Override public String renameDocument(String documentId,String displayName)throws FileNotFoundException{writable(documentId,DocumentsContract.Document.FLAG_SUPPORTS_RENAME);File source=file(documentId),target=new File(source.getParentFile(),clean(displayName));if(target.exists()||!source.renameTo(target))throw new FileNotFoundException("Rename failed");return id(target);}
    @Override public void deleteDocument(String documentId)throws FileNotFoundException{writable(documentId,DocumentsContract.Document.FLAG_SUPPORTS_DELETE);remove(file(documentId));}
    static void remove(File file)throws FileNotFoundException{File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);if(file.exists()&&!file.delete())throw new FileNotFoundException();}
    @Override public boolean isChildDocument(String parentId,String documentId){try{return file(documentId).toPath().startsWith(file(parentId).toPath());}catch(FileNotFoundException ex){return false;}}
    private String clean(String name)throws FileNotFoundException{if(name.isEmpty()||name.equals(".")||name.equals("..")||name.contains("/")||name.contains("\\"))throw new FileNotFoundException("Invalid name");return name;}
}
